import type { RunStatus } from './status.ts'
import { formatAgo, formatClock, freshnessState, utcTitle, type FreshnessState } from './time.ts'
import { usePageVisibility, useTimeZone } from './useNow.ts'
import type { ResourceMeta } from './useResource.ts'

const GLYPH: Record<FreshnessState, string> = { live: '●', watching: '●', stale: '▲', finished: '○', hidden: '' }

/**
 * The live chip (docs/PRD_VIEWER_UX.md 6.3, `live-status` with `data-state`): whether the shown run is still polled and how
 * fresh its data is. `meta` is the polled run resource's and `now` ticks at the run view. The chip is not a live region,
 * since its age changes every second; a separate polite status announces the stale state once.
 */
export function LiveStatus({ status, meta, now }: { status: RunStatus; meta: ResourceMeta; now: number }) {
  const { visible, since } = usePageVisibility()
  const [zone] = useTimeZone()
  const state = freshnessState({ status, settledAt: meta.settledAt, failures: meta.failures, visible, visibleSince: since, now })
  const loadedAt = meta.settledAt === null ? null : new Date(meta.settledAt).toISOString()
  const loadedClock = loadedAt === null ? null : formatClock(loadedAt, { zone, seconds: true, now })
  const updated = meta.settledAt === null ? '' : ` · updated ${formatAgo(meta.settledAt, now)}`
  let text: React.ReactNode
  if (state === 'live') text = `Live${updated}`
  else if (state === 'watching') text = `Watching${updated}`
  else if (state === 'finished') text = 'Finished · not polling'
  else if (state === 'hidden') text = 'Paused while this tab is hidden'
  else text = <>Not updating{loadedAt !== null && <> · showing data from <time dateTime={loadedAt} title={utcTitle(loadedAt)}>{loadedClock}</time></>} · retrying</>
  return (
    <>
      <span className={`live-status live-status-${state}`} data-testid="live-status" data-state={state}>
        {GLYPH[state] && <span aria-hidden="true">{GLYPH[state]} </span>}
        {text}
      </span>
      <span className="visually-hidden" role="status">
        {state === 'stale' ? `Not updating: showing data from ${loadedClock ?? 'an earlier load'}; retrying.` : ''}
      </span>
    </>
  )
}
/**
 * Clock hooks for the Projects viewer (docs/PRD_VIEWER_UX.md 5.3 and 6.3): the ticking current time, the page's
 * visibility, which day is today, the remembered Local/UTC preference shared by every shown time, and the instant a run
 * page reads its times against.
 */
import { createContext, useContext, useEffect, useState, useSyncExternalStore } from 'react'
import type { Zone } from './time.ts'

/** The current time, re-read every `intervalMs` while `active` and the page is visible; it does not tick otherwise. */
export function useNow(active: boolean, intervalMs = 1000): number {
  const [now, setNow] = useState(() => Date.now())
  useEffect(() => {
    if (!active) return
    const tick = () => { if (document.visibilityState === 'visible') setNow(Date.now()) }
    const timer = window.setInterval(tick, intervalMs)
    document.addEventListener('visibilitychange', tick)
    return () => {
      window.clearInterval(timer)
      document.removeEventListener('visibilitychange', tick)
    }
  }, [active, intervalMs])
  return now
}

/** Whether the page is visible, and since when: the moment it last became visible, or the first render. */
export function usePageVisibility(): { visible: boolean; since: number } {
  const [state, setState] = useState(() => ({ visible: document.visibilityState === 'visible', since: Date.now() }))
  useEffect(() => {
    const update = () => setState({ visible: document.visibilityState === 'visible', since: Date.now() })
    document.addEventListener('visibilitychange', update)
    return () => document.removeEventListener('visibilitychange', update)
  }, [])
  return state
}

// Today, for every time read against it (lists, a run's start): one value for the whole page that changes only when the
// local or the UTC date does. It is re-checked every minute and when the tab becomes visible again, so a page left open
// past midnight relabels its days without re-rendering every second.
const DAY_CHECK_MS = 60_000
let today = Date.now()
const todayListeners = new Set<() => void>()
let dayTimer: number | undefined

const dayOf = (time: number) => {
  const date = new Date(time)
  return `${date.toDateString()}|${date.toISOString().slice(0, 10)}`
}

function checkDay() {
  const now = Date.now()
  if (dayOf(now) === dayOf(today)) return
  today = now
  todayListeners.forEach(listener => listener())
}

function subscribeToday(listener: () => void): () => void {
  todayListeners.add(listener)
  if (todayListeners.size === 1) {
    checkDay()
    dayTimer = window.setInterval(checkDay, DAY_CHECK_MS)
    document.addEventListener('visibilitychange', checkDay)
  }
  return () => {
    todayListeners.delete(listener)
    if (todayListeners.size > 0) return
    window.clearInterval(dayTimer)
    document.removeEventListener('visibilitychange', checkDay)
  }
}

/** An instant of today (epoch milliseconds), for reading which day a time falls on; it changes once the date does. */
export function useToday(): number {
  return useSyncExternalStore(subscribeToday, () => today, () => today)
}

/** Where the Local/UTC choice is remembered in this browser. */
export const TIME_ZONE_STORAGE_KEY = 'mdm.projects.timezone'

// One preference for the whole page, so the toggle switches every shown time at once. Storage can be unavailable (a
// private window, blocked site data): reads then fall back to Local and a choice lasts until the page is left.
let storedZone: Zone | null = null
const zoneListeners = new Set<() => void>()

function currentZone(): Zone {
  if (storedZone === null) {
    try {
      storedZone = window.localStorage.getItem(TIME_ZONE_STORAGE_KEY) === 'utc' ? 'utc' : 'local'
    } catch {
      storedZone = 'local'
    }
  }
  return storedZone
}

function subscribeZone(listener: () => void): () => void {
  zoneListeners.add(listener)
  return () => { zoneListeners.delete(listener) }
}

function setZone(zone: Zone) {
  storedZone = zone
  try {
    window.localStorage.setItem(TIME_ZONE_STORAGE_KEY, zone)
  } catch {
    // Not remembered; the page still switches.
  }
  zoneListeners.forEach(listener => listener())
}

/** The remembered zone every time is shown in, and the setter the toggle uses. */
export function useTimeZone(): [Zone, (zone: Zone) => void] {
  const zone = useSyncExternalStore(subscribeZone, currentZone, () => 'local' as const)
  return [zone, setZone]
}

/** The instant a run page reads its times against (the run's start): a time on another day shows its date. Null reads against today. */
export const TimeReferenceContext = createContext<string | null>(null)

export function useTimeReference(): string | null {
  return useContext(TimeReferenceContext)
}
import { useEffect, useState } from 'react'

/** How often a live Projects page re-reads its run state. */
export const POLL_INTERVAL_MS = 5000

/**
 * A counter that ticks every `intervalMs` while `active` and the page is visible, and once more as the page becomes
 * visible again; pass it as a resource's `pollToken` to re-read live state in the background.
 */
export function usePoll(active: boolean, intervalMs = POLL_INTERVAL_MS): number {
  const [tick, setTick] = useState(0)
  useEffect(() => {
    if (!active) return
    const next = () => { if (document.visibilityState === 'visible') setTick(previous => previous + 1) }
    const timer = window.setInterval(next, intervalMs)
    document.addEventListener('visibilitychange', next)
    return () => {
      window.clearInterval(timer)
      document.removeEventListener('visibilitychange', next)
    }
  }, [active, intervalMs])
  return tick
}
import { useCallback, useEffect, useRef, useState } from 'react'
import type { Resource } from './resource.ts'

export type { Resource } from './resource.ts'

/** How fresh a resource is (docs/PRD_VIEWER_UX.md 6.3): the live chip's ages, the Refresh button's busy state and the failed-Refresh notice read it. */
export type ResourceMeta = {
  /** When the shown data last loaded successfully (epoch milliseconds); null before the first success. */
  settledAt: number | null
  /** The error of the latest load while loads fail; null once one succeeds. */
  lastError: unknown
  /** Loads that failed since the last success; a failed background load keeps the data shown. */
  failures: number
  /** A Refresh is loading in the background while the previous value stays shown. */
  refreshing: boolean
  /** The error of a Refresh that failed while data was shown, until a later load succeeds; null otherwise. */
  refreshError: unknown
}

type Settled<T> = { base: string; refresh: number; value: Resource<T>; settledAt: number | null; lastError: unknown; failures: number; refreshError: unknown }

/**
 * Loads one read-only resource identified by `key`. A null key means nothing to load. Changing the key or
 * calling `reload` starts a fresh request and abandons the previous one; a stale response never wins
 * because every request is aborted once the next one starts, and a settled value is tagged with the key and attempt
 * that produced it.
 * `refreshToken` (the header Refresh button) and `pollToken` (live polling) both reload in the background: the last
 * settled value stays shown while it loads, and a failed reload keeps the last loaded data instead of replacing it with an
 * error. `meta` says when the data last loaded, how many loads failed since, whether a Refresh is still loading, and
 * whether the last Refresh failed, so the page can say that what it shows may be outdated.
 */
export function useResource<T>(key: string | null, load: (signal: AbortSignal) => Promise<T>, refreshToken = 0, pollToken = 0): { state: Resource<T>; reload: () => void; meta: ResourceMeta } {
  const [settled, setSettled] = useState<Settled<T> | null>(null)
  const [attempt, setAttempt] = useState(0)
  const loadRef = useRef(load)
  useEffect(() => { loadRef.current = load }, [load])
  const base = key === null ? null : `${key}\u0000${attempt}`
  const token = base === null ? null : `${base}\u0000${refreshToken}\u0000${pollToken}`

  useEffect(() => {
    if (token === null || base === null) return
    const controller = new AbortController()
    loadRef.current(controller.signal).then(
      data => {
        if (controller.signal.aborted) return
        setSettled({ base, refresh: refreshToken, value: { status: 'ready', data }, settledAt: Date.now(), lastError: null, failures: 0, refreshError: null })
      },
      error => {
        if (controller.signal.aborted) return
        setSettled(previous => {
          const same = previous !== null && previous.base === base ? previous : null
          const failures = (same?.failures ?? 0) + 1
          // The first load to settle after a Refresh answers it; a failed poll keeps the outcome of the last Refresh.
          const answersRefresh = same !== null && same.refresh !== refreshToken
          return same !== null && same.value.status === 'ready'
            ? { ...same, refresh: refreshToken, lastError: error, failures, refreshError: answersRefresh ? error : same.refreshError }
            : { base, refresh: refreshToken, value: { status: 'error', error }, settledAt: same?.settledAt ?? null, lastError: error, failures, refreshError: null }
        })
      },
    )
    return () => controller.abort()
  }, [base, token, refreshToken])

  const reload = useCallback(() => setAttempt(previous => previous + 1), [])
  const current = settled !== null && settled.base === base ? settled : null
  const state: Resource<T> = token === null ? { status: 'idle' } : current !== null ? current.value : { status: 'loading' }
  const meta: ResourceMeta = {
    settledAt: current?.settledAt ?? null,
    lastError: current?.lastError ?? null,
    failures: current?.failures ?? 0,
    refreshing: current !== null && current.refresh !== refreshToken,
    refreshError: current?.refreshError ?? null,
  }
  return { state, reload, meta }
}

