export async function fetchWorkflowRuns(projectId: string, workflows: readonly WorkflowDefinition[], cutoff: number | null, signal?: AbortSignal): Promise<WorkflowRuns[]> {
  return Promise.all(workflows.map(async (workflow): Promise<WorkflowRuns> => {
    const runs: RunSummary[] = []
    try {
      let cursor: string | null = null
      do {
        const page: RunPage = await fetchRuns(projectId, workflow.workflow_id, { cursor }, signal)
        runs.push(...page.runs)
        const last = page.runs.at(-1)
        cursor = cutoff !== null && last !== undefined && Date.parse(last.updated_at) >= cutoff ? page.nextCursor : null
      } while (cursor !== null)
      return { workflow, runs, error: null }
    } catch (error) {
      if (signal?.aborted) throw error
      return { workflow, runs, error }
    }
  }))
}

/**
 * Runs home's rows across the registry (docs/PRD_VIEWER_UX.md 4.1): each project's workflows, then each workflow's runs
 * back to `cutoff`. Requests: one workflow list per project and at least one run page per workflow, all in parallel.
 */
export async function fetchRegistryRuns(projects: readonly Project[], cutoff: number, signal?: AbortSignal): Promise<ProjectRuns[]> {
  return Promise.all(projects.map(async (project): Promise<ProjectRuns> => {
    let workflows: WorkflowDefinition[]
    try {
      workflows = await fetchWorkflows(project.project_id, signal)
    } catch (error) {
      if (signal?.aborted) throw error
      return { project, workflows: [], error }
    }
    return { project, workflows: await fetchWorkflowRuns(project.project_id, workflows, cutoff, signal), error: null }
  }))
}

