                  <span className="projects-card-title">{project.name}</span>
                  <span className="projects-muted">
                    {project.project_id}
                    {facts && <> · {facts.features}{facts.lastRun !== null && <> · last run {formatAgo(facts.lastRun, now)}</>}</>}
                  </span>
                </AppLink>
              </li>
            )
          })}
        </ul>
      </section>
    </>
  )
}

